{"summary":"使用每个扫描周期更新的 start 上升沿记忆，并在 stop 或 permit 无效时优先清零 running；running 仅在允许条件下由 start 上升沿置位并保持。","code":"FUNCTION_BLOCK InterlockedStart
VAR_INPUT
    start : BOOL;
    stop : BOOL;
    permit : BOOL;
END_VAR
VAR_OUTPUT
    running : BOOL;
END_VAR
VAR
    previousStart : BOOL := FALSE;
    startRising : BOOL;
END_VAR

startRising := start AND NOT previousStart;
previousStart := start;

IF stop OR NOT permit THEN
    running := FALSE;
ELSIF startRising THEN
    running := TRUE;
END_IF;

END_FUNCTION_BLOCK","assumptions":[]}
